import re

from taf.selenium.core.exceptions import TooManyFilesFoundException
from taf.selenium.sbts import sbts

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_operation
from taf.rfrl.procedures.resources.python.status_check.status_selector.StatusSelector import StatusSelector

from taf.rfrl.procedures.resources.python.webui.engine import Engine
from taf.rfrl.procedures.resources.python.webui.exceptions import FileNotFound, IncorrectCountOfFiles


class SbtsEngine(Engine):

    def __init__(self, sw_stream):
        super(Engine, self).__init__()
        self._api = sbts()
        self._sw_stream = sw_stream

    def __str__(self):
        return "SbtsEngine webui instance for {0} stream".format(self._sw_stream)

    @log_input_and_output
    def block_cell(self, cell_id, timeout):
        """
        Blocks cell
        :param cell_id: index of cell to be blocked
        :type cell_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._api.block_cell(cell_idx=cell_id, timeout=timeout)

    @log_input_and_output
    def check_if_cell_is_blocked(self, cell_id):
        """
        Checks if cell is blocked by its statuses
        :param cell_id: index of cell
        :type cell_id: int
        :return: True if cell is blocked, False otherwise
        :rtype: boolean
        """
        cell_info = self._api.get_cell_info(cell_idx=cell_id)
        oper_state = cell_info['Status']['Operational state']
        av_status = cell_info['Status'].get('Availability status', None)
        blc_state = cell_info['Status']['Blocking state']

        status_selector = StatusSelector()
        disabled = status_selector.select_operational_state(variant='disabled')
        offline = status_selector.select_availability_status(variant='offline')

        return oper_state == disabled and av_status == offline and blc_state == 'Blocked'

    @log_input_and_output
    def unblock_cell(self, cell_id, timeout):
        """
        Unblocks cell
        :param cell_id: index of cell to be unblocked
        :type cell_id: int
        :param timeout: timeout
        :type timeout: int
        """
        self._api.unblock_cell(cell_idx=cell_id, timeout=timeout)

    @log_input_and_output
    def check_if_cell_is_unblocked(self, cell_id):
        """
        Checks if cell is unblocked by its statuses
        :param cell_id: index of cell
        :type cell_id: int
        :return: True if cell is unblocked, False otherwise
        :rtype: boolean
        """
        cell_info = self._api.get_cell_info(cell_idx=cell_id)
        oper_state = cell_info['Status']['Operational state']
        av_status = cell_info['Status'].get('Availability status', None)
        blc_state = cell_info['Status']['Blocking state']

        status_selector = StatusSelector()
        enabled = status_selector.select_operational_state(variant='enabled')
        online = status_selector.select_availability_status(variant='online')

        return oper_state == enabled and av_status == online and blc_state == 'Unblocked'

    @log_input_and_output
    def block_ru(self, ru_index, timeout):
        """
        Blocks RU
        :param ru_index: index of RU
        :type ru_index: int or str
        :param timeout: timeout
        :type timeout: int
        :return: status after locking RU
        :rtype: str
        """
        return self._api.block_ru(ru_index=ru_index, timeout=timeout)

    @log_input_and_output
    def unblock_ru(self, ru_index, timeout):
        """
        Unblocks RU
        :param ru_index: index of RU
        :type ru_index: int
        :param timeout: timeout
        :type timeout: int
        :return: status after unlocking RU
        :rtype: str
        """
        return self._api.unblock_ru(ru_index=ru_index, timeout=timeout)

    @log_input_and_output
    def login(self, url, username, password, screenshot_dir, download_dir, browser, sync_full_rack):
        """
        Logs in and disables message box
        :param url: url
        :type url: str
        :param username: username to log in
        :type username: str
        :param password: password to log in
        :type password: str
        :param screenshot_dir: directory where the screenshots will be saved
        :type screenshot_dir: str
        :param download_dir: directory for downloading files
        :type download_dir: str
        :param browser: WebDriver instance or "Chrome" or "Firefox" or alias name for self-created webdriver
        :type browser: Optional[WebDriver, str]
        :param sync_full_rack: states if full rack synchronization should be performed
        :type sync_full_rack: bool
        """
        sync_full_rack = [{'modal_name': "Additional hardware detected", 'button': "close", 'timeout': 30}] \
            if sync_full_rack else None

        self._api.login(url=url, username=username, password=password, screenshot_dir=screenshot_dir,
                        download_dir=download_dir, version=self._sw_stream, browser=browser,
                        modal_action_configurations=sync_full_rack)
        self._api.disable_message_box()

    @log_input_and_output
    def get_hw_monitoring(self, object_name, measured_object, timeout):
        """
        Gets hardware monitoring measurements from "Hardware monitoring" in Performance Management.
        :param object_name: object name, such as 'RMOD'
        :type object_name: str
        :param measured_object: measured object
        :type measured_object: str
        :param timeout: time to wait to get real time measurements counters
        :type timeout: int
        :return: real time measurement counters
        :rtype: dict
        """
        return self._api.get_hw_monitoring(object_name=object_name, measured_object=measured_object, timeout=timeout)

    @log_input_and_output
    def lock_baseband(self, bbmod_id, timeout):
        """
        Locks bbmod with id provided.

        :param bbmod_id: bbmod id (taken from distName, i.e. BBMOD-1 -> bbmod_id=1) which should be locked.
        :param bbmod_id: int
        :param timeout: timeout for operation
        :param timeout: int
        """
        self._api.lock_baseband(baseband_idx=bbmod_id, timeout=timeout)

    @log_input_and_output
    def unlock_baseband(self, bbmod_id, timeout):
        """
        Unlocks bbmod with id provided.

        :param bbmod_id: bbmod id (taken from distName, i.e. BBMOD-1 -> bbmod_id=1) which should be unlocked.
        :param bbmod_id: int
        :param timeout: timeout for operation
        :param timeout: int
        """
        self._api.unlock_baseband(baseband_idx=bbmod_id, timeout=timeout)

    @log_input_and_output
    def reset_nr(self, cancel, timeout):
        """
        Resetting NR RAT on the top of web page

        :param cancel: if cancel reset, default False
        :type timeout: bool
        :param timeout: timeout for operation
        :type timeout: int
        """
        self._api.reset_nr(cancel=cancel,
                           timeout=timeout)

    @log_input_and_output
    def select_antenna_lines_for_monitoring(self, antenna_lines, timeout):
        """
        Select antenna lines.
        :param antenna_lines: default None, will choose all antenna lines. If need to choose specific antenna, you
                              could pass a dict like below:
                              {"RMOD-1/RMOD_R-1(AHPF)": ["ANT1", "ANT3"],
                               "RMOD-2/RMOD_R-2(AHPF)": ["ANT2", "ANT4"]}
        :type antenna_lines: None type or dict
        :param timeout: timeout for operation
        :type timeout: int
        """
        self._api.select_antenna_lines_for_monitoring(antenna_lines=antenna_lines,
                                                      timeout=timeout)

    @log_input_and_output
    def start_antenna_line_monitoring(self, timeout):
        """
         Start antenna lines monitoring.

        :param timeout: timeout for operation
        :type timeout: int
        :return: status
        :rtype: str
        """
        return self._api.start_antenna_line_monitoring(timeout=timeout)

    @log_input_and_output
    def stop_antenna_line_monitoring(self, timeout):
        """
         Stop antenna lines monitoring.

        :param timeout: timeout for operation
        :type timeout: int
        :return: status
        :rtype: str
        """
        return self._api.stop_antenna_line_monitoring(timeout=timeout)

    @log_input_and_output
    def get_monitored_values(self, value_type, timeout):
        """
        Gets monitored values.

        :param value_type: default None, will return all monitored values.
        Otherwise return specific monitored type value.
        :type value_type: dict
        :param timeout: timeout for operation
        :type timeout: int
        :return: monitored values
        :rtype: dict
        """
        return self._api.get_monitored_values(value_type=value_type,
                                              timeout=timeout)

    @log_input_and_output
    def export_monitored_value_to_csv(self, timeout):
        """
        Export monitored valued to csv and return path to file. When exception TooManyFilesFoundException raises,
        method will try to find proper path to csv file, based on files list included in exception message.

        :param timeout: timeout for operation
        :type timeout: int
        :return: path to csv file
        :rtype: str
        """
        try:
            return self._api.export_monitored_value_to_csv(timeout=timeout)
        except TooManyFilesFoundException as exc:
            return self._get_path_to_csv_file_when_TooManyFilesFoundException(exception=exc)

    def add_object(self, object_name, object_class_name, plan_to_copy_from, copy_from,
                   include_subobject, id_value, is_load_default_values, timeout):
        """
        Adds object under navigation panel. For SW stream >= SBTS25R2 both `plan_to_copy_from` and `copy_from` must be
        provided if user wants to copy object from existing one, otherwise a new object will be created.
        :param object_name: where object will be added in, e.g. 'MRBTS-50138/NRBTS-1'
        :type object_name: str
        :param object_class_name: name of object class, e.g. 'NRCELL'
        :type object_class_name: str
        :param plan_to_copy_from: from which plan to copy object from, default is None
                                  for SW stream < SBTS25R2, e.g. 'CONF-1'
                                  for SW stream >= SBTS25R2, e.g. 'CONF-1_SBTS_azhl_10MHz' ('CONF-1_' + SCF name)
        :type plan_to_copy_from: str
        :param copy_from: where copy object from, e.g. '/MRBTS-50138/NRBTS-1/NRCELL-1'. Default is None
        :type copy_from: str
        :param include_subobject: True if user want to include subobject, default is False.
        :type include_subobject: bool
        :param id_value: id value of new object, default is None
        :type id_value: str
        :param is_load_default_values: True if user want to select default value, False otherwise
                                       (works for SW stream < SBTS25R2)
        :type is_load_default_values: bool
        :param timeout: timeout, default is 60
        :type timeout: int
        """
        if self._sw_stream < "SBTS25R2":
            self._api.add_object(object_name=object_name, object_class_name=object_class_name,
                                 plan_to_copy_from=plan_to_copy_from, copy_from=copy_from,
                                 include_subobject=include_subobject, id_value=id_value,
                                 is_load_default_values=is_load_default_values, timeout=int(timeout))
        else:
            if plan_to_copy_from and copy_from:
                log_operation("Copy existing object for adding an object")
                self._api.copy_existing_object(object_name=object_name,
                                               class_name=object_class_name,
                                               source_plan_name=plan_to_copy_from,
                                               source_managed_object=copy_from,
                                               copy_object_with_subtree=include_subobject,
                                               object_id=id_value,
                                               timeout=int(timeout))
            else:
                log_operation("Create new object for adding an object")
                self._api.add_new_object(object_name=object_name, class_name=object_class_name, object_id=id_value,
                                         timeout=int(timeout))

    @log_input_and_output
    def activate_plan(self, download_plan_without_activation=False, activate_plan_despite_errors=False, execute=True,
                      timeout=60):
        """
        Activates plan after loading scf file
        :param download_plan_without_activation: if False, download plan without activation will not be selected
        :type download_plan_without_activation: bool
        :param activate_plan_despite_errors: if True, activate plan despite of validation errors will be selected
        :type activate_plan_despite_errors: bool
        :param execute: if True, click execute button, otherwise close the activate plan modal
        :type execute: bool
        :param timeout: timeout
        :type timeout: int
        :return: True if activation succeeded or False otherwise
        :rtype: bool
        """
        activation_status = self._api.activate_plan(
            download_plan_without_activation=download_plan_without_activation,
            activate_plan_despite_errors=activate_plan_despite_errors,
            execute=execute,
            timeout=int(timeout))

        if type(activation_status) is str:
            return activation_status == 'Plan activation has finished successfully.'

        return activation_status

    @log_input_and_output
    def _get_path_to_csv_file_when_TooManyFilesFoundException(self, exception):
        """
        Gets path to downloaded csv file based on files list from TooManyFilesFoundException exception message.

        :param exception: TooManyFilesFoundException exception
        :type exception: Exception

        :return: path to downloaded csv file
        :rtype: str
        """
        file_list = re.findall(r'/[^\s+]*/[^/]*\.csv', str(exception))

        if not file_list:
            raise FileNotFound(f"Csv file is not found in downloaded list. "
                               f"TooManyFilesFoundException message is {exception}")

        if len(file_list) > 1:
            raise IncorrectCountOfFiles(f"More then one csv file found: {file_list}")

        return file_list[0]
